import sys

if hasattr(sys, "set_int_max_str_digits"):
    sys.set_int_max_str_digits(0)

_WS = "\x20\t\n\r"


def _skip_ws(s: str, n: int) -> int:
    i = 0
    while i < n:
        c = s[i]
        if c not in _WS:
            return i
        i += 1
    return i


def _parse_string(s: str, n: int, start: int) -> tuple[bool, int]:
    if start >= n or s[start] != '"':
        return False, -1
    i = start + 1
    while True:
        if i >= n:
            return False, -1
        c = s[i]
        if c == '"':
            return True, i + 1
        if c == "\\":
            i += 1
            if i >= n:
                return False, -1
            esc = s[i]
            i += 1
            if esc == '"':
                continue
            if esc == "\\":
                continue
            if esc == "/":
                continue
            if esc == "b":
                continue
            if esc == "f":
                continue
            if esc == "n":
                continue
            if esc == "r":
                continue
            if esc == "t":
                continue
            if esc == "u":
                if i + 4 > n:
                    return False, -1
                h1 = s[i : i + 4]
                code1 = int(h1, 16)
                if 0xD800 <= code1 <= 0xDBFF:
                    if i + 4 > n or s[i] != "u":
                        return False, -1
                    h2 = s[i : i + 4]
                    code2 = int(h2, 16)
                    if not (0xDC00 <= code2 <= 0xDFFF):
                        return False, -1
                    i += 8
                elif 0xDC00 <= code1 <= 0xDFFF:
                    if i < n and s[i] == "u":
                        return False, -1
                    return False, -1
                elif code1 == 0x0000:
                    i += 4
                elif code1 > 0x007F:
                    if i < n and s[i] == "u":
                        return False, -1
                    return False, -1
                else:
                    if i < n and s[i] == "u":
                        return False, -1
                    return False, -1
            return False, -1
        if 0x0000 <= ord(c) <= 0x001F:
            return False, -1
        if c == "\uFEFF" or 0xD800 <= ord(c) <= 0xDFFF:
            return False, -1
        i += 1


def _parse_number(s: str, n: int, start: int) -> tuple[bool, int, object]:
    if start >= n:
        return False, -1, None

    sign = 1
    pos = start
    if s[pos] == "-":
        sign = -1
        pos += 1
        if pos >= n:
            return False, -1, None

    if pos < n and s[pos] == "0":
        if pos + 1 < n and (s[pos + 1] == "." or s[pos + 1] == "e" or s[pos + 1] == "E"):
            pos += 1
        else:
            return True, pos + 1, 0 if sign == 1 else 0
    elif pos < n and "1" <= s[pos] <= "9":
        pos += 1
        while pos < n and "0" <= s[pos] <= "9":
            pos += 1
        if pos < n and s[pos] in ".eE":
            pos += 1
            if pos < n and s[pos] in "+-":
                pos += 1
            if pos >= n or not ("0" <= s[pos] <= "9"):
                return False, -1, None
            pos += 1
            while pos < n and "0" <= s[pos] <= "9":
                pos += 1
            return True, pos, float(s[start:pos])
        return True, pos, int(s[start:pos])
    else:
        return False, -1, None


def _parse_object_member(s: str, n: int, start: int) -> tuple[bool, int, object, object]:
    i = _skip_ws(s, n)
    if i >= n:
        return False, -1, None, None

    if s[i] == "}":
        return True, i + 1, None, None

    if i >= n or s[i] != '"':
        return False, -1, None, None
    key_start = i
    ok, i = _parse_string(s, n, i)
    if not ok:
        return False, -1, None, None
    key = s[key_start:i]

    i = _skip_ws(s, n)
    if i >= n or s[i] != ":":
        return False, -1, None, None
    i += 1
    return True, i, key, None


def _parse_value(s: str, n: int, start: int, parent=None, key=None):
