            return _parse_object_member if s[i] == "," else _parse_value
        if s[i] == "[":
            parent = []
            parent_kind = "array"
            return _parse_object_member if s[i + 1] == "{" or s[i + 1] == "}" else _parse_value
        if s[i] == "{":
            parent = {}
            parent_kind = "object"
            return _parse_object_member
        return _parse_value
    if s[i] == '"':
        if parent_kind == "scalar":
            ok, ni = _parse_string(s, n, i)
            if not ok:
                return None
            return ni
        if parent_kind == "object":
            if key is not None:
                if key in parent:
                    return None
                parent[key] = None
            if s[i + 1] == "}":
                return parent, i + 2
            return _parse_object_member if s[i] == "," else _parse_value
        return _parse_object_member if s[i] == "," else _parse_value

    return _parse_value


def parse_json(text: str) -> object:
    n = len(text)
    if n == 0:
        return None

    i = _skip_ws(text, n)
    if i >= n:
